html:
{% set barcode_value = "" %}
{% if doc.barcodes and doc.barcodes|length > 0 %}
    {% set barcode_value = doc.barcodes[0].barcode %}
{% endif %}

{% set company_name = frappe.db.get_default("company") or frappe.db.get_single_value("Global Defaults", "default_company") or "" %}

{% set price_list = doc.custom_price_list or frappe.db.get_single_value("Selling Settings", "selling_price_list") or "Standard Selling" %}

{% set selling_price = frappe.db.get_value(
    "Item Price",
    {
        "item_code": doc.item_code,
        "price_list": price_list,
        "selling": 1
    },
    "price_list_rate"
) or 0 %}

{% set currency = frappe.db.get_value("Price List", price_list, "currency") or frappe.db.get_value("Company", company_name, "default_currency") or "" %}

<style>
    @page {
        size: 60mm 40mm;
        margin: 0;
    }

    html,
    body {
        width: 60mm;
        height: 40mm;
        margin: 0 !important;
        padding: 0 !important;
    }

    .print-format {
        width: 60mm !important;
        min-height: 40mm !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    .barcode-label {
        box-sizing: border-box;
        width: 60mm;
        height: 40mm;
        padding: 2mm;
        overflow: hidden;
        background: #fff;
        color: #000;
        font-family: Arial, sans-serif;
        font-weight: bold;
        display: table;
        table-layout: fixed;
    }

    .left-col,
    .middle-col,
    .right-col {
        display: table-cell;
        vertical-align: middle;
        height: 36mm;
    }

    .left-col {
        width: 15mm;
    }

    .middle-col {
        width: 25mm;
        text-align: center;
    }

    .right-col {
        width: 16mm;
        text-align: center;
        position: relative;
    }

    .weight {
        font-size: 7pt;
        line-height: 1;
        margin-bottom: 5mm;
        white-space: nowrap;
    }

    .price {
        font-size: 15pt;
        line-height: 1;
        margin-bottom: 5mm;
        white-space: nowrap;
    }

    .currency {
        font-size: 8pt;
        margin-right: 1mm;
    }

    .dates {
        font-size: 7pt;
        line-height: 1.35;
        white-space: nowrap;
    }

    .barcode-svg {
        width: 24mm;
        height: 22mm;
    }

    .barcode-number {
        font-size: 14pt;
        line-height: 1;
        letter-spacing: 1px;
        margin-top: -1mm;
    }

    .vertical-text {
        position: absolute;
        left: 50%;
        top: 50%;
        width: 36mm;
        transform: translate(-50%, -50%) rotate(90deg);
        transform-origin: center;
        text-align: center;
    }

    .company-name {
        font-size: 9pt;
        line-height: 1.1;
        white-space: nowrap;
        margin-bottom: 2mm;
    }

    .item-name {
        font-size: 7pt;
        line-height: 1.1;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
</style>

<div class="barcode-label">

    <div class="left-col">
        <div class="weight">
            WT:
            {% if doc.weight_per_unit %}
                {{ doc.weight_per_unit|int if doc.weight_per_unit == doc.weight_per_unit|int else doc.weight_per_unit }}
                {{ doc.weight_uom or "" }}
            {% else %}
                {{ doc.stock_uom or "" }}
            {% endif %}
        </div>

        <div class="price">
            <span class="currency">{{ currency }}</span>{{ "%.2f"|format(selling_price|float) }}
        </div>

        <div class="dates">
            <div>
                Prd.
                {% if doc.custom_production_date %}
                    {{ frappe.utils.formatdate(doc.custom_production_date, "dd-MM-yyyy") }}
                {% endif %}
            </div>

            <div>
                Exp.
                {% if doc.custom_expiry_date %}
                    {{ frappe.utils.formatdate(doc.custom_expiry_date, "dd-MM-yyyy") }}
                {% endif %}
            </div>
        </div>
    </div>

    <div class="middle-col">
        {% if barcode_value %}
            <svg
                class="barcode barcode-svg"
                jsbarcode-value="{{ barcode_value }}"
                jsbarcode-format="CODE128"
                jsbarcode-displayvalue="false"
                jsbarcode-margin="0"
                jsbarcode-height="60">
            </svg>

            <div class="barcode-number">
                {{ barcode_value }}
            </div>
        {% endif %}
    </div>

    <div class="right-col">
        <div class="vertical-text">
            <div class="company-name">
                {{ company_name }}
            </div>

            <div class="item-name">
                {{ doc.item_name or doc.item_code }}
            </div>
        </div>
    </div>

</div>

<script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script>

<script>
    if (typeof JsBarcode !== "undefined") {
        JsBarcode(".barcode").init();
    }
</script>
